'data'=>['Data Source',[['maps_source','Default Google Maps source','select',['places'=>'Google Places API (New) – up to 60 results','serpapi'=>'SerpAPI Google Maps – 100+ results']],['google_api_key','Google Cloud API key','secret',null,'Enable "Places API (New)" (and optionally "PageSpeed Insights API") at console.cloud.google.com → APIs & Services. Billing must be enabled; Google gives a monthly free credit.'],['serpapi_key','SerpAPI key','secret',null,'serpapi.com → Dashboard → API key. Needed for more than 60 listings per search.'],['maps_language','Language code'],['maps_region','Region code (e.g. in, us, ae)'],['default_country_code','Default country calling code (for WhatsApp)'],['pagespeed','Run Google PageSpeed test in audits','select',['0'=>'No (faster)','1'=>'Yes (adds ~20s per site)']],['timezone','Timezone','select',array_combine($tz,$tz)]]],
'email'=>['Email',[['smtp_host','SMTP host','text',null,'Example: smtp.hostinger.com, mail.yourdomain.com, smtp.gmail.com, smtp-relay.brevo.com'],['smtp_port','SMTP port'],['smtp_secure','Encryption','select',['ssl'=>'SSL (465)','tls'=>'TLS / STARTTLS (587)','none'=>'None']],['smtp_user','SMTP username'],['smtp_pass','SMTP password','secret'],['from_email','From email'],['from_name','From name'],['reply_to','Reply-to email'],['bcc_email','BCC copy to (optional)'],['imap_host','IMAP host (to detect replies)','text',null,'Usually the same mailbox. Example: imap.hostinger.com or mail.yourdomain.com. Leave empty to disable reply detection.'],['imap_port','IMAP port'],['imap_user','IMAP username (blank = SMTP username)'],['imap_pass','IMAP password (blank = SMTP password)','secret']]],
