$tab=isset($T[$_GET['tab']??''])?$_GET['tab']:'company';
if(is_post()){
  $a=$_POST['a']??'save';
  try{
  if($a==='save'){
    foreach($T[$tab][1] as $f){
      [$k,,$type]=$f+[2=>'text'];
      if($type==='file'){
        if(empty($_FILES[$k]['tmp_name'])||!is_uploaded_file($_FILES[$k]['tmp_name']))continue;
        $ext=strtolower(pathinfo($_FILES[$k]['name'],PATHINFO_EXTENSION));
        if(!in_array('.'.$ext,explode(',',$f[3]),true))throw new Exception('Invalid file type for '.$f[1]);
        if($k==='font_upload'){$n=preg_replace('/[^a-z0-9_-]+/i','-',pathinfo($_FILES[$k]['name'],PATHINFO_FILENAME));move_uploaded_file($_FILES[$k]['tmp_name'],STORAGE.'/fonts/'.$n.'.ttf');flash('Font "'.e($n).'" uploaded.');continue;}
        $dir=$k==='company_logo'?'assets/uploads':'storage/uploads';@mkdir(ROOT.'/'.$dir,0755,true);
        $dst=$dir.'/'.$k.'-'.token(4).'.'.$ext;
        move_uploaded_file($_FILES[$k]['tmp_name'],ROOT.'/'.$dst);
        Settings::set($k,$dst);continue;}
      if($type==='secret'){if(($_POST[$k]??'')!=='')Settings::set($k,trim($_POST[$k]));if(!empty($_POST['clear_'.$k]))Settings::set($k,'');continue;}
      if(array_key_exists($k,$_POST))Settings::set($k,trim($_POST[$k]));}
    if($tab==='pricing'&&!empty($_POST['currency'])&&isset($cur[$_POST['currency']])&&($_POST['currency_symbol']??'')==='')Settings::set('currency_symbol',$cur[$_POST['currency']]);
    if($tab==='whatsapp'&&setting('wa_api_headers')&&json_decode(setting('wa_api_headers'))===null)flash('Custom headers are not valid JSON.','err');
    if($tab==='proposal'&&!empty($_POST['remove_proposal'])){Settings::set('proposal_pdf','');}
    flash('Settings saved.');}
  if($a==='test_email'){Mailer::send(user()['email'],'Anvesha test email','<p>Your SMTP settings work.</p>','Your SMTP settings work.');flash('Test email sent to '.e(user()['email']).'.');}
  if($a==='test_imap'){$s=Mailer::inboxSenders(3);flash('IMAP connected. '.count($s).' sender(s) in the last 3 days.');}
  if($a==='test_wa'){$to=trim($_POST['to']??'');$id=WhatsApp::send($to,'Test message from Anvesha ✅',[],['business_name'=>'Test','sender_name'=>setting('sender_name')]);flash($id==='manual'?'Manual mode: <a href="'.e(WhatsApp::link($to,'Test message from Anvesha')).'" target="_blank">open WhatsApp</a>':'WhatsApp test sent ('.e($id).').');}
  if($a==='test_maps'){$city=trim($_POST['city']??'')?:'Pune';if(setting('maps_source','places')==='places'){$d=Maps::diagnose($city);flash(implode('<br>',array_map('e',$d)),strpos(end($d),'✓')===0?'ok':'err');}else{$r=Maps::search('cafe in '.$city,null,'serpapi');flash('SerpAPI works – got '.count($r['items']).' listings, e.g. '.e($r['items'][0]['name']??'—').'.');}}
  if($a==='password'){
    $u=DB::row('SELECT * FROM users WHERE id=?',[user()['id']]);
    if(!password_verify($_POST['old']??'',$u['password']))throw new Exception('Current password is wrong.');
    if(strlen($_POST['new']??'')<8)throw new Exception('New password must be at least 8 characters.');
    DB::update('users',['password'=>password_hash($_POST['new'],PASSWORD_DEFAULT),'name'=>trim($_POST['name']??$u['name']),'email'=>trim($_POST['email']??$u['email'])],'id=?',[$u['id']]);flash('Account updated.');}
  if($a==='adduser'){if(strlen($_POST['pw']??'')<8)throw new Exception('Password must be at least 8 characters.');DB::insert('users',['name'=>trim($_POST['name']),'email'=>trim($_POST['email']),'password'=>password_hash($_POST['pw'],PASSWORD_DEFAULT)]);flash('User added.');}
  if($a==='deluser'&&(int)$_POST['id']!==(int)user()['id']){DB::q('DELETE FROM users WHERE id=?',[(int)$_POST['id']]);flash('User removed.');}
  }catch(Throwable $e){flash(e($e->getMessage()),'err');}
  redirect(url('settings',['tab'=>$tab]));}
$field=function($f){
  [$k,$label,$type,$opt,$help]=$f+[2=>'text',3=>null,4=>''];
  $v=setting($k);
  $o='<label class="'.($type==='textarea'?'full':'').'">'.e($label);
  if($type==='textarea')$o.='<textarea name="'.$k.'" rows="'.($k==='services'||$k==='company_address'?4:3).'" class="'.(strpos($k,'wa_api')===0?'mono':'').'">'.e($v).'</textarea>';
  elseif($type==='select'){$o.='<select name="'.$k.'">';foreach($opt as $ov=>$ol)$o.='<option value="'.e($ov).'" '.((string)$v===(string)$ov?'selected':'').'>'.e($ol).'</option>';$o.='</select>';}
  elseif($type==='secret')$o.='<input type="password" name="'.$k.'" autocomplete="new-password" placeholder="'.($v!==''?'•••••••• saved – type to replace':'Not set').'">'.($v!==''?'<span class="chk sm"><input type="checkbox" name="clear_'.$k.'" value="1"> remove</span>':'');
  elseif($type==='file'){$o.='<input type="file" name="'.$k.'" accept="'.e($opt).'">';if($v&&$k==='company_logo')$o.='<span class="logo-pv" style="background:'.e(setting('brand_primary','#0B0B0B')).'"><img src="'.e($v).'" alt=""></span>';elseif($v&&$k==='proposal_pdf')$o.='<span class="sm">Current: <b>'.e(basename($v)).'</b> <span class="chk sm"><input type="checkbox" name="remove_proposal" value="1"> remove</span></span>';}
  elseif($type==='color')$o.='<span class="clr"><input type="color" value="'.e($v).'" oninput="this.nextElementSibling.value=this.value"><input name="'.$k.'" value="'.e($v).'" oninput="this.previousElementSibling.value=this.value"></span>';
  else $o.='<input type="'.($type==='number'?'number':'text').'" name="'.$k.'" value="'.e($v).'">';
  if($help)$o.='<small>'.(strpos($help,'http')!==false?preg_replace('~(https?://\S+)~','<code>$1</code>',e($help)):e($help)).'</small>';
  return $o.'</label>';};
?>
