<form method="post" enctype="multipart/form-data" class="card frm"><?=csrf_field()?><input type="hidden" name="a" value="save"><div class="card-h"><h3><?=e($T[$tab][0])?></h3></div><div class="fg"><?php foreach($T[$tab][1] as $f)echo $field($f);?></div><div class="row"><button class="btn btn-g"><?=icon('check')?>Save settings</button></div></form>
