<?php if($tab==='branding'):?><div class="card"><h4>Preview</h4><div class="bprev" style="background:<?=e(setting('brand_primary'))?>"><img src="<?=e(setting('company_logo'))?>" alt=""><div><small style="color:<?=e(setting('brand_accent'))?>">FREE DIGITAL GROWTH AUDIT</small><b>Website &amp; Google Maps Audit</b><span style="color:<?=e(setting('brand_accent'))?>">Prepared for Sample Business</span></div></div></div><?php endif?>
